require_once __DIR__.'/../includes/location_bootstrap.php';
ensure_sri_lanka_locations($pdo);
$id=(int)($_GET['id']??0);
$st=$pdo->prepare("SELECT p.*,u.name,u.email,u.phone,d.province_id FROM providers p JOIN users u ON u.id=p.user_id LEFT JOIN districts d ON d.id=p.district_id WHERE p.id=? LIMIT 1");$st->execute([$id]);$p=$st->fetch();if(!$p)exit('Provider not found.');
$cats=$pdo->query("SELECT id,name FROM service_categories WHERE status='active' ORDER BY id")->fetchAll();$types=$pdo->query("SELECT id,name FROM vehicle_types WHERE status='active' ORDER BY id")->fetchAll();$provinces=$pdo->query('SELECT id,name FROM provinces ORDER BY id')->fetchAll();
$q=$pdo->prepare('SELECT category_id FROM provider_services WHERE provider_id=?');$q->execute([$id]);$selCats=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$pdo->prepare('SELECT vehicle_type_id FROM provider_vehicle_types WHERE provider_id=?');$q->execute([$id]);$selTypes=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $province=(int)($_POST['province_id']??0);$district=(int)($_POST['district_id']??0);$city=(int)($_POST['city_id']??0);$maps=trim($_POST['google_maps_link']??'');$lat=($_POST['latitude']??'')!==''?(float)$_POST['latitude']:null;$lng=($_POST['longitude']??'')!==''?(float)$_POST['longitude']:null;$acc=($_POST['location_accuracy']??'')!==''?(float)$_POST['location_accuracy']:null;$cat=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['category_ids']??[])))));$typ=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['vehicle_type_ids']??[])))));
  if($maps!==''){[$mlat,$mlng]=extract_google_maps_coordinates($maps);if($mlat!==null&&$mlng!==null){$lat=$mlat;$lng=$mlng;$acc=null;}}
  if(!$province||!$district||!$city||$lat===null||$lng===null)throw new RuntimeException('Complete the service location and map coordinates.');if(!$cat||!$typ)throw new RuntimeException('Select at least one service category and vehicle type.');
  $q=$pdo->prepare('SELECT id FROM districts WHERE id=? AND province_id=?');$q->execute([$district,$province]);if(!$q->fetchColumn())throw new RuntimeException('Invalid district.');ensure_sri_lanka_cities($pdo,$district);$q=$pdo->prepare('SELECT id FROM cities WHERE id=? AND district_id=?');$q->execute([$city,$district]);if(!$q->fetchColumn())throw new RuntimeException('Invalid town/area.');
  $pdo->beginTransaction();$pdo->prepare('UPDATE users SET name=?,email=?,phone=? WHERE id=?')->execute([trim($_POST['owner_name']),trim($_POST['email']),trim($_POST['phone']),$p['user_id']]);$pdo->prepare('UPDATE providers SET business_name=?,owner_name=?,whatsapp=?,address=?,google_maps_link=?,latitude=?,longitude=?,location_accuracy=?,district_id=?,city_id=?,description=?,emergency_24h=?,approval_status=? WHERE id=?')->execute([trim($_POST['business_name']),trim($_POST['owner_name']),trim($_POST['whatsapp']),trim($_POST['address']),$maps!==''?$maps:null,$lat,$lng,$acc,$district,$city,trim($_POST['description']),isset($_POST['emergency'])?1:0,$_POST['approval_status']??'approved',$id]);
  $pdo->prepare('DELETE FROM provider_services WHERE provider_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO provider_services(provider_id,category_id) VALUES(?,?)');foreach($cat as $x)$ins->execute([$id,$x]);$pdo->prepare('DELETE FROM provider_vehicle_types WHERE provider_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO provider_vehicle_types(provider_id,vehicle_type_id) VALUES(?,?)');foreach($typ as $x)$ins->execute([$id,$x]);$newStatus=($_POST['approval_status']??'approved')==='approved'?'active':(($_POST['approval_status']??'approved')==='disabled'?'disabled':'pending');$pdo->prepare('UPDATE users SET status=? WHERE id=?')->execute([$newStatus,$p['user_id']]);$pdo->commit();$msg='Provider details updated.';$st->execute([$id]);$p=$st->fetch();$selCats=$cat;$selTypes=$typ;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
