<section class="section-pad"><div class="container"><div class="col-lg-10 mx-auto card border-0 shadow-sm p-4 rounded-4"><div class="d-flex justify-content-between align-items-center"><div><h2 class="fw-bold mb-1">Edit Provider</h2><p class="text-muted mb-0">Administrator control over provider account, services and station location.</p></div><a class="btn btn-outline-secondary" href="providers.php">Back</a></div><?php if($msg):?><div class="alert alert-success mt-3"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger mt-3"><?=e($error)?></div><?php endif;?><form method="post" class="row g-3 mt-1">
