<div class="col-12"><div class="border rounded-4 p-3 bg-light-subtle"><label class="form-label fw-semibold">Vehicle types serviced *</label><div class="row g-2"><?php foreach($types as $t):?><div class="col-sm-6 col-lg-4"><label class="form-check border rounded-3 p-2 ps-5 bg-white"><input class="form-check-input" type="checkbox" name="vehicle_type_ids[]" value="<?=$t['id']?>" <?=in_array((int)$t['id'],$selTypes,true)?'checked':''?>> <?=e($t['name'])?></label></div><?php endforeach;?></div></div></div>
<div class="col-12"><div class="border rounded-4 p-3 bg-light-subtle"><label class="form-label fw-semibold">Service categories *</label><div class="row g-2"><?php foreach($cats as $c):?><div class="col-sm-6 col-lg-3"><label class="form-check border rounded-3 p-2 ps-5 bg-white"><input class="form-check-input" type="checkbox" name="category_ids[]" value="<?=$c['id']?>" <?=in_array((int)$c['id'],$selCats,true)?'checked':''?>> <?=e($c['name'])?></label></div><?php endforeach;?></div></div></div>
<div class="col-md-4"><label class="form-label">Province</label><select class="form-select" id="ep" name="province_id" required><?php foreach($provinces as $x):?><option value="<?=$x['id']?>" <?=$x['id']==(int)$p['province_id']?'selected':''?>><?=e($x['name'])?> Province</option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">District</label><select class="form-select" id="ed" name="district_id" required></select></div><div class="col-md-4"><label class="form-label">Town / Area</label><select class="form-select" id="ec" name="city_id" required></select></div>
<div class="col-12"><label class="form-label">Service address</label><input class="form-control" name="address" value="<?=e($p['address']??'')?>" required></div><div class="col-12"><label class="form-label">Google Maps location link</label><input class="form-control" id="eg" name="google_maps_link" value="<?=e($p['google_maps_link']??'')?>"></div>
<div class="col-12"><div class="location-picker"><label class="location-label">Exact service station location *</label><div class="location-search-wrapper"><i class="bi bi-geo-alt location-search-icon"></i><input class="location-search" id="es" placeholder="Search service location..."></div><div class="location-actions"><button type="button" class="current-location-btn" id="egps"><i class="bi bi-crosshair"></i> Use current location</button><button type="button" class="btn btn-outline-primary btn-sm ms-2" id="eguse"><i class="bi bi-link-45deg"></i> Use Google Maps link</button><span id="est" class="location-status"></span></div><div id="emap" class="location-map"></div></div><input type="hidden" name="latitude" id="elat" value="<?=e((string)$p['latitude'])?>"><input type="hidden" name="longitude" id="elng" value="<?=e((string)$p['longitude'])?>"><input type="hidden" name="location_accuracy" id="eacc" value="<?=e((string)$p['location_accuracy'])?>"></div>
