<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const ep=document.getElementById('ep'),ed=document.getElementById('ed'),ec=document.getElementById('ec');let sd=<?=json_encode((int)$p['district_id'])?>,sc=<?=json_encode((int)$p['city_id'])?>;async function ld(){ed.disabled=true;ed.innerHTML='<option>Loading districts...</option>';const r=await fetch('../customer/get-districts.php?province_id='+ep.value),a=await r.json();ed.innerHTML='<option value="">Select district</option>';a.forEach(x=>{let o=document.createElement('option');o.value=x.id;o.textContent=x.name+' District';if(+x.id===sd)o.selected=true;ed.appendChild(o)});ed.disabled=!a.length;if(ed.value)lc(ed.value)}async function lc(id){ec.disabled=true;ec.innerHTML='<option>Loading towns...</option>';const r=await fetch('../customer/get-cities.php?district_id='+id),a=await r.json();ec.innerHTML='<option value="">Select town / area</option>';a.forEach(x=>{let o=document.createElement('option');o.value=x.id;o.textContent=x.name;if(+x.id===sc)o.selected=true;ec.appendChild(o)});ec.disabled=!a.length}ep.onchange=()=>{sd=0;sc=0;ld()};ed.onchange=()=>{sc=0;lc(ed.value)};ld();
const em=L.map('emap').setView([<?=json_encode($p['latitude']!==null?(float)$p['latitude']:7.8731)?>,<?=json_encode($p['longitude']!==null?(float)$p['longitude']:80.7718)?>],<?=json_encode($p['latitude']!==null?16:7)?>);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(em);let emk=null;const es=document.getElementById('es'),eg=document.getElementById('eg'),est=document.getElementById('est');function setE(lat,lng,addr='',acc=''){elat.value=Number(lat).toFixed(8);elng.value=Number(lng).toFixed(8);eacc.value=acc!==''?Number(acc).toFixed(2):'';if(addr)es.value=addr;em.setView([lat,lng],17);if(!emk){emk=L.marker([lat,lng],{draggable:true}).addTo(em);emk.on('dragend',()=>{let x=emk.getLatLng();setE(x.lat,x.lng,'','')})}else emk.setLatLng([lat,lng]);est.textContent='Service station location selected.';}function pg(u){let m=u.match(/@(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/);if(!m)m=u.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/);if(!m)m=u.match(/[?&](?:q|query|ll|center)=(-?\d+(?:\.\d+)?)[,%2C]+(-?\d+(?:\.\d+)?)/i);return m?[+m[1],+m[2]]:null;}document.getElementById('eguse').onclick=()=>{let c=pg(eg.value);if(c)setE(c[0],c[1],eg.value,'');else est.textContent='Could not read coordinates from this link.'};document.getElementById('egps').onclick=()=>navigator.geolocation.getCurrentPosition(x=>setE(x.coords.latitude,x.coords.longitude,'',x.coords.accuracy),()=>est.textContent='Location permission was denied or unavailable.',{enableHighAccuracy:true});es.oninput=()=>{let q=es.value.trim();if(q.length<3)return;fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=lk&q='+encodeURIComponent(q)).then(r=>r.json()).then(a=>{if(a[0])setE(a[0].lat,a[0].lon,a[0].display_name,'')})};em.on('click',e=>setE(e.latlng.lat,e.latlng.lng,'',''));<?php if($p['latitude']!==null&&$p['longitude']!==null):?>setE(<?=json_encode((float)$p['latitude'])?>,<?=json_encode((float)$p['longitude'])?>,'',<?=json_encode($p['location_accuracy'])?>);<?php endif;?>
</script><?php require __DIR__.'/../includes/footer.php'; ?>
